/** Authorization outcome for the read. On the loopback single-user dashboard a
legal local read is [`Self::Authorized`]; the other variants are retained so
the contract can express `unauthorized` (identity absent/expired), `denied`
(known identity lacks permission), and `redacted` reads without a schema
change. */
export const DashboardAuthorizationV1Schema = z.discriminatedUnion("outcome", [z.object({
  outcome: z.literal("authorized"),
}), z.object({
  outcome: z.literal("denied"),
}), z.object({
  outcome: z.literal("redacted"),
}), z.object({
  outcome: z.literal("unauthorized"),
})]);
export type DashboardAuthorizationV1 = z.infer<typeof DashboardAuthorizationV1Schema>;

/** Coverage completeness axis. `Unsupported` distinguishes "the source that
would establish coverage is not wired" from `Unknown` ("coverage could not
be determined"). */
export const DashboardCoverageCompletenessV1Schema = z.enum(["complete", "partial", "unknown", "unsupported"]);
export type DashboardCoverageCompletenessV1 = z.infer<typeof DashboardCoverageCompletenessV1Schema>;

/** Coverage statement. Counts are optional; an unknown denominator is `None`,
never a fabricated `0`/`100%`. The completeness axis is authoritative — the
frontend never derives `complete` from a `matched == eligible` coincidence. */
export const DashboardCoverageV1Schema = z.object({
  completeness: z.lazy(() => DashboardCoverageCompletenessV1Schema),
  denominator: z.number().int().safe().min(0).nullable(),
  eligible: z.number().int().safe().min(0).nullable(),
  examined: z.number().int().safe().min(0).nullable(),
  excluded: z.number().int().safe().min(0).nullable(),
  matched: z.number().int().safe().min(0).nullable(),
  omission_reasons: z.array(z.string()),
  omitted: z.number().int().safe().min(0).nullable(),
  unit: z.string().nullable(),
  unknown: z.number().int().safe().min(0).nullable(),
});
export type DashboardCoverageV1 = z.infer<typeof DashboardCoverageV1Schema>;

/** The normative dashboard domain-state union.

The first sixteen variants are the plan's exact `DashboardDomainState`
discriminated union. [`Self::Unsupported`] is the backend-gap binding
state: the read model's HTTP surface exists, but its live producer/source is
not yet wired server-side. It is never healthy or empty — the frontend
renders a distinct "not yet available" state — and it is deliberately
separate from [`Self::UnsupportedSchema`] (an undecodable schema/variant). */
export const DashboardDomainStateV1Schema = z.union([z.enum(["cancelled", "complete_zero_findings", "conflicting", "denied", "error", "loading", "locked", "offline", "partial", "ready", "redacted", "stale", "timed_out", "unauthorized", "unknown", "unsupported_schema"]), z.literal("unsupported")]).catch("unsupported_schema");
export type DashboardDomainStateV1 = z.infer<typeof DashboardDomainStateV1Schema>;

/** The normative read-model envelope. Every V2 read-model route returns exactly
this shape; only `payload` varies by route. */
export interface DashboardEnvelopeV1<TPayload> {
  authorization: DashboardAuthorizationV1;
  coverage: DashboardCoverageV1;
  domain_state: DashboardDomainStateV1;
  freshness: DashboardFreshnessV1;
  legal_actions: Array<DashboardLegalActionRefV1>;
  payload: TPayload;
  schema_revision: 1;
  scope: DashboardScopeV1;
  source_watermark: DashboardWatermarkV1 | null;
  time: DashboardTimeV1;
  version: DashboardVersionV1;
}

export function DashboardEnvelopeV1Schema<TPayload>(
  payloadSchema: z.ZodType<TPayload>,
): z.ZodType<DashboardEnvelopeV1<TPayload>> {
  return z.object({
    authorization: z.lazy(() => DashboardAuthorizationV1Schema),
    coverage: z.lazy(() => DashboardCoverageV1Schema),
    domain_state: z.lazy(() => DashboardDomainStateV1Schema),
    freshness: z.lazy(() => DashboardFreshnessV1Schema),
    legal_actions: z.array(z.lazy(() => DashboardLegalActionRefV1Schema)),
    payload: payloadSchema,
    schema_revision: z.literal(1),
    scope: z.lazy(() => DashboardScopeV1Schema),
    source_watermark: z.union([z.lazy(() => DashboardWatermarkV1Schema), z.null()]),
    time: z.lazy(() => DashboardTimeV1Schema),
    version: z.lazy(() => DashboardVersionV1Schema),
  }) as unknown as z.ZodType<DashboardEnvelopeV1<TPayload>>;
}

